<script setup>
import { ref,onMounted,computed } from 'vue'
import { api } from '../api'
import { useWorkflowWrite } from '../composables/useWorkflowWrite'
const data=ref(null),candidates=ref(null),goals=ref([]),events=ref([]),judgments=ref([]),error=ref(''),notice=ref(''),goalId=ref(null),mainlineId=ref(null),eventId=ref(null),minutes=ref(null),result=ref(false),evidence=ref('')
const candidate=ref({name:'',metric:'diary_content_days',shape:'total_days',target:null,start:'',end:''}),writes=useWorkflowWrite('growth-policies')
const availableEvents=computed(()=>events.value.filter(e=>e.record_kind!=='diary'&&judgments.value.some(j=>j.event_id===e.id&&['pending','adjusted'].includes(j.status))))
async function load(){const values=await Promise.all([api.flow('/mainlines'),api.flow('/dynamic-candidates'),api.listGoals(),api.records(),api.listJudgments()]);[data.value,candidates.value,goals.value,events.value,judgments.value]=values}
async function act(fn){if(writes.busy.value)return;error.value='';notice.value='';try{await fn()}catch(e){error.value=e.message}}
async function addMainline(){await act(async()=>{await writes.send('/mainlines',{goal_id:goalId.value,active:true});await load()})}
async function preview(){await act(async()=>{const mainline=data.value.items.find(r=>r.id===mainlineId.value),event=events.value.find(e=>e.id===eventId.value),judgment=judgments.value.find(j=>j.event_id===event.id&&['pending','adjusted'].includes(j.status));await writes.send('/reward-previews',{mainline_id:mainline.id,mainline_version:mainline.version,event_id:event.id,event_version:event.content_version,judgment_id:judgment.id,minutes:minutes.value,result:result.value,evidence:evidence.value});await load()})}
async function confirm(row){await act(async()=>{await writes.send('/judgments/'+row.judgment_id+'/confirm',{expected_version:row.snapshot.judgment_version,reward_preview_id:row.id});notice.value='已按展示的建议和规则确认入账。';await load()})}
async function propose(){await act(async()=>{await writes.send('/dynamic-candidates',{...candidate.value,start:candidate.value.start||null,end:candidate.value.end||null});await load()})}
onMounted(()=>load().catch(e=>{error.value=e.message}))
</script>
<template><div class="policy-workflows"><p v-if="error" class="error" role="alert">{{ error }}</p><p v-if="notice" role="status">{{ notice }}</p><p v-if="writes.pending.value">上次操作结果未知，再次操作恢复原请求，不另造结算。</p>
<section class="card"><h2>主线 · 有效投入与成果</h2><p class="muted">{{ data?.rule?.enabled?'按已确认规则预览；确认前不会发奖。':'正式金额、上限与叠加规则未开通，旧经济继续可用。' }}</p><form @submit.prevent="addMainline"><label>关联已有目标<select v-model="goalId" required><option :value="null">请选择目标</option><option v-for="goal in goals" :value="goal.id" :key="goal.id">{{ goal.description }}</option></select></label><button class="btn" :disabled="writes.busy.value">保存主线关联</button></form><article v-for="row in data?.items||[]" :key="row.id"><p>{{ goals.find(g=>g.id===row.goal_id)?.description||'历史目标' }} · {{ row.active?'启用关联':'已停用' }}</p><button class="btn" :disabled="writes.busy.value" @click="act(async()=>{await writes.send('/mainlines/'+row.id,{expected_version:row.version,goal_id:row.goal_id,active:!row.active},'PUT');await load()})">{{ row.active?'停用关联':'启用关联' }}</button></article>
<details><summary>按实际事实预览奖励</summary><form @submit.prevent="preview"><label>本次主线<select v-model="mainlineId" required><option :value="null">选择主线</option><option v-for="row in data?.items.filter(r=>r.active)||[]" :key="row.id" :value="row.id">{{ goals.find(g=>g.id===row.goal_id)?.description }}</option></select></label><label>有待确认建议的事件<select v-model="eventId" required><option :value="null">选择事件</option><option v-for="event in availableEvents" :key="event.id" :value="event.id">{{ event.title||event.content.slice(0,50) }}</option></select></label><label>有效投入分钟<input type="number" step="any" min="0" v-model.number="minutes" required/></label><label><input type="checkbox" v-model="result"/>有可以核对的成果</label><label>投入与成果事实依据<textarea v-model="evidence" maxlength="2000" required/></label><button class="btn" :disabled="writes.busy.value||!data?.rule?.enabled">生成预览</button></form></details>
<article v-for="row in data?.previews||[]" :key="row.id"><h3>{{ row.snapshot.event.title||'事件' }} · {{ row.state==='confirmed'?'已确认':'待确认预览' }}</h3><p>主线奖励 {{ row.amount }} 币 · {{ row.snapshot.tier?.code||'未达档位' }} · 规则 v{{ row.snapshot.rule.version }}</p><p>{{ row.snapshot.evidence }}</p><details><summary>规则与来源快照</summary><p>{{ row.snapshot.rule.payload.stacking==='stack'?'与原日常奖励叠加':'替代本次原日常奖励' }} · 上限归属日 {{ row.snapshot.cap_date }}</p><p>原文 v{{ row.snapshot.event.content_version }} · 有效投入 {{ row.snapshot.minutes }} 分钟 · {{ row.snapshot.result?'有成果':'未声明成果' }}</p></details><button v-if="row.state==='pending'" class="btn primary" :disabled="writes.busy.value" @click="confirm(row)">确认建议与此奖励入账</button></article></section>
<section class="card"><h2>核实型成就候选</h2><p class="muted">名称不决定奖励。分别核对日期指标、范围与目标；一个自然月不等同30天。未配置金额时只显示候选，不沿用旧发现型50币。</p><details><summary>提出可核实候选</summary><form @submit.prevent="propose"><label>名称<input v-model="candidate.name" maxlength="100" required/></label><label>指标<select v-model="candidate.metric"><option value="diary_content_days">日记内容覆盖日</option><option value="diary_saved_days">日记首次保存日</option><option value="event_content_days">事件内容覆盖日</option><option value="event_saved_days">事件首次保存日</option></select></label><label>条件<select v-model="candidate.shape"><option value="total_days">累计天数</option><option value="consecutive_days">连续天数</option><option value="calendar_month">完整自然月</option></select></label><label>目标（自然月填1）<input type="number" v-model.number="candidate.target" min="1" required/></label><div class="form-grid"><label>起始日期<input type="date" v-model="candidate.start"/></label><label>结束日期<input type="date" v-model="candidate.end"/></label></div><button class="btn" :disabled="writes.busy.value">保存并核实候选</button></form></details>
<article v-for="row in candidates?.items||[]" :key="row.id"><h3>{{ row.name }}</h3><p>{{ {candidate:'待处理候选',claimed:'已领取',ignored:'已忽略'}[row.state] }} · 已核实 {{ row.evidence.count }}/{{ row.evidence.target }} 天 · {{ row.evidence.eligible?'证据满足':'证据尚不足' }}</p><details><summary>指标身份与来源</summary><p>{{ row.criteria.metric }} · {{ row.criteria.shape }} · {{ row.criteria.start||'不限起日' }}～{{ row.criteria.end||'不限止日' }}</p><code>{{ row.semantic_key }}</code><p>事实版本 {{ row.evidence.sources?.map(r=>'#'+r.id+' v'+r.version).join('，') }}</p></details><div v-if="row.state==='candidate'" class="action-group"><button v-for="(label,action) in {verify:'重新核实',ignore:'忽略候选',claim:'领取已配置奖励'}" :key="action" class="btn" :disabled="writes.busy.value||(action==='claim'&&(!candidates.rule?.enabled||candidates.rule.payload.rewards[row.semantic_key]===undefined))" @click="act(async()=>{await writes.send('/dynamic-candidates/'+row.id+'/decision',{expected_version:row.version,action});await load()})">{{ label }}</button></div></article></section></div></template>
